paragraph.math:
$$\begin{array}{l}
  {\frac{\partial f}{\partial x} = {\cos\left( \frac{x}{1 + y} \right) \cdot \frac{\partial}{\partial x}\left( \frac{x}{1 + y} \right) = \cos\left( \frac{x}{1 + y} \right) \cdot \frac{1}{1 + y}}} \\
  {\frac{\partial f}{\partial y} = {\cos\left( \frac{x}{1 + y} \right) \cdot \frac{\partial}{\partial y}\left( \frac{x}{1 + y} \right) = - \cos\left( \frac{x}{1 + y} \right) \cdot \frac{x}{(1 + y)^{2}}}}
  \end{array}$$

$$\begin{array}{l}
  {\left( f_{x} \right)_{x} = f_{xx} = f_{11} = \frac{\partial}{\partial x}\left( \frac{\partial f}{\partial x} \right) = \frac{\partial^{2}f}{\partial x^{2}} = \frac{\partial^{2}z}{\partial x^{2}}} \\
  {\left( f_{x} \right)_{y} = f_{xy} = f_{12} = \frac{\partial}{\partial y}\left( \frac{\partial f}{\partial x} \right) = \frac{\partial^{2}f}{\partial y\partial x} = \frac{\partial^{2}z}{\partial y\partial x}} \\
  {\left( f_{y} \right)_{x} = f_{yx} = f_{21} = \frac{\partial}{\partial x}\left( \frac{\partial f}{\partial y} \right) = \frac{\partial^{2}f}{\partial x\partial y} = \frac{\partial^{2}z}{\partial x\partial y}} \\
  {\left( f_{y} \right)_{y} = f_{yy} = f_{22} = \frac{\partial}{\partial y}\left( \frac{\partial f}{\partial y} \right) = \frac{\partial^{2}f}{\partial y^{2}} = \frac{\partial^{2}z}{\partial y^{2}}}
  \end{array}$$

$$\begin{array}{ll}
  {f_{xx} = \frac{\partial}{\partial x}{({3x^{2} + 2xy^{3}})} = 6x + 2y^{3}} & {\qquad f_{xy} = \frac{\partial}{\partial y}{({3x^{2} + 2xy^{3}})} = 6xy^{2}} \\
  {f_{yx} = \frac{\partial}{\partial x}{({3x^{2}y^{2} - 4y})} = 6xy^{2}} & {\qquad f_{yy} = \frac{\partial}{\partial y}{({3x^{2}y^{2} - 4y})} = 6x^{2}y - 4}
  \end{array}$$

$$\begin{matrix}
  u_{x} & = & {e^{ x}\sin y} & {\qquad u_{y}} & = & {e^{ x}\cos y} \\
  u_{xx} & = & {e^{ x}\sin y} & {\qquad u_{yy}} & = & {- e^{ x}\sin y}
  \end{matrix}$$

$$\begin{array}{rclrcl}
  u_{x} & = & {\cos{({x - at})}} & {\mspace{54mu} u_{t}} & = & {- a\cos(x - at)} \\
  u_{xx} & = & {- \sin{({x - at})}} & {\mspace{54mu} u_{tt}} & = & {- a^{2}\sin{({x - at})} = a^{2}u_{xx}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial z}{\partial s} = \frac{\partial z}{\partial x}\frac{\partial x}{\partial s} + \frac{\partial z}{\partial y}\frac{\partial y}{\partial s} = (e^{ x}\sin{y)(t}^{2}) + (e^{ x}\cos y)(2st)} \\
  {{\frac{\partial z}{\partial t} = \frac{\partial z}{\partial x}\frac{\partial x}{\partial t} + \frac{\partial z}{\partial y}\frac{\partial y}{\partial t}} = (e^{ x}\sin y)(2st) + (e^{ x}\cos y)(s^{2})}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial z}{\partial s} = t^{2}e^{ st^{2}}\sin{({s^{2}t})} + 2ste^{ st^{2}}\cos{({s^{2}t})}} \\
  {\frac{\partial z}{\partial t} = 2ste^{ st^{2}}\sin{({s^{2}t})} + s^{2}e^{ st^{2}}\cos{({s^{2}t})}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial w}{\partial u} = \frac{\partial w}{\partial x}\frac{\partial x}{\partial u} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial u} + \frac{\partial w}{\partial z}\frac{\partial z}{\partial u} + \frac{\partial w}{\partial t}\frac{\partial t}{\partial u}} \\
  {\frac{\partial w}{\partial\upsilon} = \frac{\partial w}{\partial x}\frac{\partial x}{\partial\upsilon} + \frac{\partial w}{\partial y}\frac{\partial y}{\partial\upsilon} + \frac{\partial w}{\partial z}\frac{\partial z}{\partial\upsilon} + \frac{\partial w}{\partial t}\frac{\partial t}{\partial\upsilon}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial u}{\partial s} = \frac{\partial u}{\partial x}\frac{\partial x}{\partial s} + \frac{\partial u}{\partial y}\frac{\partial y}{\partial s} + \frac{\partial u}{\partial z}\frac{\partial z}{\partial s}} \\
  {\phantom{\frac{\partial u}{\partial s}}{= {({4x^{3}y})}{({re^{ t}})} + {({x^{4} + 2yz^{3}})}{({2rse^{- t}})} + {({3y^{2}z^{2}})}{({r^{2}\sin t})}}}
  \end{array}$$

$$\begin{array}{lll}
  \frac{\partial g}{\partial s} & = & {\frac{\partial f}{\partial x}\frac{\partial x}{\partial s} + \frac{\partial f}{\partial y}\frac{\partial y}{\partial s} = \frac{\partial f}{\partial x}(2s) + \frac{\partial f}{\partial y}( - 2s)} \\
  \frac{\partial g}{\partial t} & = & {\frac{\partial f}{\partial x}\frac{\partial x}{\partial t} + \frac{\partial f}{\partial y}\frac{\partial y}{\partial t} = \frac{\partial f}{\partial x}( - 2t) + \frac{\partial f}{\partial y}(2t)}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial^{2}z}{\partial r^{2}} = \frac{\partial}{\partial r}\left( {2r\frac{\partial z}{\partial x} + 2s\frac{\partial z}{\partial y}} \right)} \\
  {\phantom{\frac{\partial^{2}z}{\partial r^{2}}} = 2\frac{\partial z}{\partial x} + 2r\frac{\partial}{\partial r}\left( \frac{\partial z}{\partial x} \right) + 2s\frac{\partial}{\partial r}\left( \frac{\partial z}{\partial y} \right)}
  \end{array}$$

$$\begin{array}{lllll}
  {\frac{\partial}{\partial r}\left( \frac{\partial z}{\partial x} \right)} & = & {\frac{\partial}{\partial x}\left( \frac{\partial z}{\partial x} \right)\frac{\partial x}{\partial r} + \frac{\partial}{\partial y}\left( \frac{\partial z}{\partial x} \right)\frac{\partial y}{\partial r}} & = & {\frac{\partial^{2}z}{\partial x^{2}}(2r) + \frac{\partial^{2}z}{\partial y\partial x}(2s)} \\
  {\frac{\partial}{\partial r}\left( \frac{\partial z}{\partial y} \right)} & = & {\frac{\partial}{\partial x}\left( \frac{\partial z}{\partial y} \right)\frac{\partial x}{\partial r} + \frac{\partial}{\partial y}\left( \frac{\partial z}{\partial y} \right)\frac{\partial y}{\partial r}} & = & {\frac{\partial^{2}z}{\partial x\partial y}(2r) + \frac{\partial^{2}z}{\partial y^{2}}(2s)}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\partial^{2}z}{\partial r^{2}} = 2\frac{\partial z}{\partial x} + 2r\left( {2r\frac{\partial^{2}z}{\partial x^{2}} + 2s\frac{\partial^{2}z}{\partial y\partial x}} \right) + 2s\left( {2r\frac{\partial^{2}z}{\partial x\partial y} + 2s\frac{\partial^{2}z}{\partial y^{2}}} \right)} \\
  {\phantom{\frac{\partial^{2}z}{\partial r^{2}}}{= 2\frac{\partial z}{\partial x} + 4r^{2}\frac{\partial^{2}z}{\partial x^{2}} + 8rs\frac{\partial^{2}z}{\partial x\partial y} + 4s^{2}\frac{\partial^{2}z}{\partial y^{2}}}}
  \end{array}$$

$$\begin{array}{lll}
  {\nabla f(x,y)} & = & {\langle f_{x},f_{y}\rangle = \langle e^{ y},xe^{ y}\rangle} \\
  {\nabla f(2,0)} & = & {\langle 1,2\rangle}
  \end{array}$$

$$\begin{array}{l}
  {\nabla T = \frac{\partial T}{\partial x}\mathbf{i} + \frac{\partial T}{\partial y}\mathbf{j} + \frac{\partial T}{\partial z}\mathbf{k}} \\
  {\phantom{\nabla T}{= - \frac{160x}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{i} - \frac{320y}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{j} - \frac{480z}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}\mathbf{k}}} \\
  {\phantom{\nabla T}{= \frac{160}{{({1 + x^{2} + 2y^{2} + 3z^{2}})}^{2}}{({- x\mathbf{i} - 2y\mathbf{j} - 3z\mathbf{k}})}}}
  \end{array}$$

$$\begin{array}{l}
  {Q(x,y) = f(a,b) + f_{x}(a,b)(x - a) + f_{y}(a,b)(y - b)} \\
  {\mspace{90mu} + \frac{1}{2}f_{xx}(a,b){(x - a)}^{2} + f_{xy}(a,b)(x - a)(y - b) + \frac{1}{2}f_{yy}(a,b){(y - b)}^{2}}
  \end{array}$$

$$\begin{array}{rcl}
  V_{x} & = & {\lambda g_{x}} \\
  V_{y} & = & {\lambda g_{y}} \\
  V_{z} & = & {\lambda g_{z}}
  \end{array}$$

$$\begin{array}{rcl}
  Q_{i} & = & {{flow\ through\ turbine}i{in\ cubic\ feet\ per\ second}} \\
  {KW_{i}} & = & {{power\ generated\ by\ turbine}i{in}{kilowatts}} \\
  Q_{T} & = & {total\ flow\ through\ the\ station\ in\ cubic\ feet\ per\ second}
  \end{array}$$
